    sg.bezierCurveTo(cx+S*0.09,cy-S*0.08,cx-S*0.07,cy+S*0.02,cx+S*0.03,cy+S*0.10);
    sg.bezierCurveTo(cx+S*0.09,cy+S*0.15,cx-S*0.01,cy+S*0.21,cx-S*0.07,cy+S*0.15);sg.stroke();
