  if(t==='lava'){ if(wxTok==='ash'&&r()<0.5) return 'volclightning'; if(r()<0.10) return 'firewhirl'; return null; }
  if(t==='desert'){ if(wxTok==='dust'&&r()<0.5) return 'haboob'; return null; }
  if(t==='ocean'){ if(wb==='stormsea'&&r()<0.7) return 'hurricane'; if(wxTok==='rain'&&r()<0.22) return 'hurricane'; return null; }
  if(t==='terran'){ if(wxTok==='rain'&&r()<0.14) return 'tornado'; if(wxTok==='snow'&&r()<0.25) return 'icestorm'; return null; }
  if(t==='ice'){ if(wb==='cryogeyser'&&r()<0.6) return 'cryoeruption'; if(wxTok==='snow'&&r()<0.2) return 'icestorm'; return null; }
  if(t==='venus'){ return r()<0.5?'virga':null; }
