  const vg4=g.createRadialGradient(W/2,H*0.45,H*0.3,W/2,H*0.5,W*0.62);
  vg4.addColorStop(0,'rgba(0,0,0,0)'); vg4.addColorStop(1,'rgba(0,2,5,0.5)');
