    const _vwnA=(function(){ try{ const q=(st.sys&&st.sys.planets)?st.sys.planets.find(x=>x&&x.P&&x.P.seed===P.seed):null; return (q&&q.name)||null; }catch(_){ return null; } })();
    const headA='<span class="vhn">The deep — '+(_vwnA?_vwnA+'</span> · <span class="vhr">'+String(wb5.n).toLowerCase()+'</span>':wb5.n+'</span>');
